#!/usr/bin/env python3
"""Audit services/ against SPEC.md and emit per-service verdicts (no writes)."""
import ast
import json
import re
import sys
from pathlib import Path

ROOT = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
SERVICES = ROOT / "services"
CLAUSES = [f"C{i}" for i in range(1, 16)]

DIGEST_RE = re.compile(r"@sha256:[0-9a-f]{64}$")


def read_text(p):
    return p.read_text(encoding="utf-8", errors="replace")


def is_lfs_pointer(p):
    try:
        with open(p, "rb") as fh:
            first = fh.readline()
    except OSError:
        return False
    return first.rstrip(b"\r\n") == b"version https://git-lfs.github.com/spec/v1"


def load_config(svc):
    p = svc / "config.json"
    try:
        return json.loads(read_text(p)), None
    except Exception as e:  # noqa: BLE001
        return None, f"{type(e).__name__}: {e}"


def is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def py_files(svc):
    return sorted((svc / "src").rglob("*.py")) if (svc / "src").is_dir() else []


def parse_py(p):
    try:
        return ast.parse(read_text(p)), None
    except SyntaxError as e:
        return None, e


def check_c2(svc, ev):
    h = svc / "src" / "handlers.py"
    if not h.is_file():
        return True, ev  # clause is about functions that exist
    tree, err = parse_py(h)
    if tree is None:
        ev.append(f"C2 unparseable handlers.py: {err}")
        return False, ev
    ok = True
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name.startswith("handle_"):
            if ast.get_docstring(node) is None:
                ok = False
                ev.append(f"C2 {h.relative_to(svc)}:{node.lineno} handle {node.name} lacks docstring")
    return ok, ev


def check_c3(svc, ev):
    ok = True
    for p in py_files(svc):
        tree, err = parse_py(p)
        if tree is None:
            ev.append(f"C3 skipped unparseable {p.relative_to(svc)}: {err}")
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "print":
                ok = False
                ev.append(f"C3 {p.relative_to(svc)}:{node.lineno} print call")
    return ok, ev


def check_c5(svc, ev):
    d = svc / "Dockerfile"
    if not d.is_file():
        ev.append("C5 missing Dockerfile")
        return False, ev
    ok = True
    for i, line in enumerate(read_text(d).splitlines(), 1):
        parts = line.strip().split()
        if not parts or parts[0].upper() != "FROM":
            continue
        rest = [t for t in parts[1:] if not t.startswith("--")]
        image = rest[0] if rest else ""
        if not DIGEST_RE.search(image):
            ok = False
            ev.append(f"C5 Dockerfile:{i} FROM image {image!r} not digest-pinned")
    return ok, ev


def check_c6(svc, ev):
    d = svc / "Dockerfile"
    if not d.is_file():
        ev.append("C6 missing Dockerfile")
        return False, ev
    last = None
    for i, line in enumerate(read_text(d).splitlines(), 1):
        parts = line.strip().split()
        if parts and parts[0].upper() == "USER":
            last = (i, parts[1] if len(parts) > 1 else "", line.strip())
    if last is None:
        ev.append("C6 no USER line")
        return False, ev
    i, user, raw = last
    name = user.split(":")[0]
    if name in ("root", "0"):
        ev.append(f"C6 Dockerfile:{i} last USER is {raw!r}")
        return False, ev
    return True, ev


def check_c7(svc, ev):
    r = svc / "README.md"
    if not r.is_file():
        ev.append("C7 missing README.md")
        return False, ev
    lines = read_text(r).splitlines()
    if "## Runbook" not in lines:
        ev.append("C7 no exact '## Runbook' line")
        return False, ev
    return True, ev


def check_c8(svc, cfg, cfg_err, ev):
    c = svc / "CODEOWNERS"
    if cfg_err:
        ev.append(f"C8 config unreadable: {cfg_err}")
        return False, ev
    if not c.is_file():
        ev.append("C8 missing CODEOWNERS")
        return False, ev
    want = "@team-" + str(cfg.get("team"))
    ok = False
    for line in read_text(c).splitlines():
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        toks = s.split()
        if toks[0] == "*" and want in toks[1:]:
            ok = True
    if not ok:
        ev.append(f"C8 no '*' rule owned by {want}")
    return ok, ev


def check_c9(svc, ev):
    ok = True
    for p in py_files(svc):
        tree, err = parse_py(p)
        if tree is None:
            ev.append(f"C9 skipped unparseable {p.relative_to(svc)}: {err}")
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                if node.value.startswith(("sk_live_", "AKIA")):
                    ok = False
                    ev.append(f"C9 {p.relative_to(svc)}:{node.lineno} literal starts {node.value[:12]!r}")
    return ok, ev


def handle_names(svc):
    h = svc / "src" / "handlers.py"
    if not h.is_file():
        return set(), "missing handlers.py"
    tree, err = parse_py(h)
    if tree is None:
        return set(), str(err)
    return {n.name for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))}, None


def check_c10(svc, cfg, cfg_err, ev):
    if cfg_err:
        ev.append(f"C10 config unreadable: {cfg_err}")
        return False, ev
    hc = cfg.get("healthcheck")
    if not hc:
        ev.append("C10 no healthcheck in config")
        return False, ev
    seg = str(hc).split("?")[0].rstrip("/").split("/")[-1]
    want = "handle_" + seg
    names, err = handle_names(svc)
    if want not in names:
        ev.append(f"C10 healthcheck {hc!r} needs {want}; {'handlers.py ' + err if err else 'not defined'}")
        return False, ev
    return True, ev


def check_c12(svc, ev):
    r = svc / "requirements.txt"
    if not r.is_file():
        ev.append("C12 missing requirements.txt")
        return False, ev
    ok = True
    for i, line in enumerate(read_text(r).splitlines(), 1):
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._\-]*(?:\[[^\]]+\])?==[^\s;]+", s):
            ok = False
            ev.append(f"C12 requirements.txt:{i} unpinned {s!r}")
    return ok, ev


def audit(svc):
    ev = []
    results = {}
    cfg, cfg_err = load_config(svc)
    results["C1"] = results["C4"] = results["C11"] = results["C13"] = results["C14"] = False
    if cfg_err is None and isinstance(cfg, dict):
        public = cfg.get("exposure") == "public"
        t = cfg.get("timeout_s")
        results["C1"] = (not public) or (is_number(t) and t <= 30)
        if public and results["C1"] is False:
            ev.append(f"C1 public timeout_s={t!r}")
        r = cfg.get("retries")
        results["C4"] = isinstance(r, int) and not isinstance(r, bool) and 1 <= r <= 5
        if not results["C4"]:
            ev.append(f"C4 retries={r!r}")
        p, m = cfg.get("port"), cfg.get("metrics_port")
        results["C11"] = p != m
        if not results["C11"]:
            ev.append(f"C11 port==metrics_port=={p!r}")
        ll = cfg.get("log_level")
        results["C13"] = ll != "DEBUG"
        if not results["C13"]:
            ev.append(f"C13 log_level={ll!r}")
        mb = cfg.get("max_body_kb")
        results["C14"] = (not public) or (is_number(mb) and mb <= 1024)
        if public and results["C14"] is False:
            ev.append(f"C14 public max_body_kb={mb!r}")
    else:
        ev.append(f"config unreadable: {cfg_err}")

    results["C2"] = check_c2(svc, ev)[0]
    results["C3"] = check_c3(svc, ev)[0]
    results["C5"] = check_c5(svc, ev)[0]
    results["C6"] = check_c6(svc, ev)[0]
    results["C7"] = check_c7(svc, ev)[0]
    results["C8"] = check_c8(svc, cfg, cfg_err, ev)[0]
    results["C9"] = check_c9(svc, ev)[0]
    results["C10"] = check_c10(svc, cfg, cfg_err, ev)[0]
    results["C12"] = check_c12(svc, ev)[0]
    tests = svc / "tests"
    results["C15"] = tests.is_dir() and any(
        p.is_file() and p.name.startswith("test_") and p.name.endswith(".py") for p in tests.iterdir()
    )
    if not results["C15"]:
        ev.append("C15 no tests/test_*.py")

    violations = [c for c in CLAUSES if not results.get(c, False)]
    return violations, ev


def main():
    out = []
    for svc in sorted(p for p in SERVICES.iterdir() if p.is_dir()):
        pointers = []
        for p in sorted(svc.rglob("*")):
            if p.is_file() and is_lfs_pointer(p):
                pointers.append(str(p.relative_to(svc)))
        if pointers:
            out.append({"service": svc.name, "status": "unverifiable", "violations": [],
                        "pointers": pointers, "evidence": []})
            continue
        violations, ev = audit(svc)
        out.append({"service": svc.name,
                    "status": "violations" if violations else "compliant",
                    "violations": violations, "pointers": [], "evidence": ev})
    print(json.dumps(out, indent=2))


if __name__ == "__main__":
    main()

