"""Drive the audit: snapshot hashes, run checker, write findings when stable."""
import hashlib
import json
import re
import subprocess
import sys
import time
from pathlib import Path

ROOT = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
CHECKER = Path("/tmp/audit_check.py")


def tree_hash():
    h = hashlib.sha256()
    for p in sorted(ROOT.rglob("*")):
        rel = p.relative_to(ROOT)
        if ".git" in rel.parts or "findings" in rel.parts:
            continue
        if p.is_file():
            h.update(str(rel).encode())
            h.update(p.read_bytes())
    return h.hexdigest()


def spec_clauses():
    found = set()
    for p in sorted(ROOT.glob("SPEC*.md")):
        found.update(re.findall(r"\*\*(C\d+)\*\*", p.read_text()))
    return found


def run_checker():
    out = subprocess.run(
        [sys.executable, str(CHECKER), str(ROOT)],
        capture_output=True, text=True, check=False,
    )
    if out.returncode != 0:
        raise SystemExit(f"checker failed: {out.stderr}")
    return json.loads(out.stdout)


def write_findings(results):
    d = ROOT / "findings"
    d.mkdir(exist_ok=True)
    for r in results:
        doc = {"service": r["service"], "status": r["status"], "violations": r["violations"]}
        (d / f"{r['service']}.json").write_text(json.dumps(doc) + "\n")


def same_as_disk(results):
    d = ROOT / "findings"
    for r in results:
        f = d / f"{r['service']}.json"
        if not f.is_file():
            return False
        want = {"service": r["service"], "status": r["status"], "violations": r["violations"]}
        if json.loads(f.read_text()) != want:
            return False
    return True


def main():
    for attempt in range(12):
        h0 = tree_hash()
        clauses = spec_clauses()
        results = run_checker()
        h1 = tree_hash()
        if h0 != h1:
            print(f"attempt {attempt}: tree changed during check, retrying")
            time.sleep(2)
            continue
        checker_clauses = {f"C{i}" for i in range(1, 17)}
        if not clauses <= checker_clauses:
            print("SPEC clause set changed:", sorted(clauses))
            print("checker does not cover:", sorted(clauses - checker_clauses))
            return 2
        if not clauses == checker_clauses:
            print("note: checker covers clauses not in spec:", sorted(checker_clauses - clauses))
        write_findings(results)
        h2 = tree_hash()
        if h2 == h1 and same_as_disk(results):
            print("stable after attempt", attempt)
            for r in results:
                print(r["service"], r["status"], r["violations"])
            return 0
        print(f"attempt {attempt}: tree changed after write, retrying")
        time.sleep(2)
    print("tree kept changing; giving up")
    return 1


if __name__ == "__main__":
    sys.exit(main())

